/** 统一账号中心接口及 DTO。 */

import axios from 'axios';
import ucenterRequest, {
  type TokenResponseData,
  type UcenterRequestConfig,
  type UcenterResponse,
} from './ucenterRequest';

// 登录注册合一流程使用 login_auto_register，其他值继续用于独立账号操作。
export type SmsCodeType = 'register' | 'login' | 'login_auto_register' | 'forget' | 'bind' | 'change';
export type EmailCodeType = 'register' | 'forget' | 'bind' | 'change' | 'recover';

export interface UcenterUser {
  uid_hash: string;
  phone: string;
  country_code?: string;
  email: string;
  nickname: string;
  avatar: string;
  status: number;
  created_at?: string;
  updated_at?: string;
}

export interface LoginData extends TokenResponseData {
  user_info?: {
    user: UcenterUser;
    set_password?: boolean;
  };
}

export interface SlideCaptchaData {
  captcha_id: string;
  image: string;
  /** 新接口返回的拼图块 Data URL。 */
  tile_image: string;
  /** 兼容旧版字段，后端全部升级后可移除。 */
  tile?: string;
  tile_width: number;
  tile_height: number;
  tile_x: number;
  tile_y: number;
}

export interface SendSmsCaptchaPayload {
  phone: string;
  country_code?: string;
  code_type: SmsCodeType;
  captcha_id: string;
  x: number;
  y: number;
}

export interface SendEmailCaptchaPayload {
  email: string;
  code_type: EmailCodeType;
  captcha_id: string;
  x: number;
  y: number;
}

export interface AvatarPostObjectData {
  upload_url: string;
  oss_path: string;
  form_data: Record<string, string>;
  max_size: number;
}

export interface AvatarSaveData {
  /** 头像审核状态：0 无头像、1 待审核、2 已通过、3 已拒绝。 */
  audit_status: number;
  message: string;
}

/** 出生日期仍由账号中心基础资料接口维护。 */
export interface UpdateUserInfoPayload {
  birthday: string;
}

const skipRefreshConfig = {_skipAuthRefresh: true} as UcenterRequestConfig;
const logoutConfig = {
  _skipAuthRefresh: true,
  _skipAccountTermination: true,
} as UcenterRequestConfig;

export const authApi = {
  /** 登录接口同时开启自动注册，新手机号无需单独走注册页。 */
  login: (phone: string, code: string) =>
    ucenterRequest.post<UcenterResponse<LoginData>>('/api/auth/login', {
      phone,
      country_code: '86',
      code,
      auto_register: true,
    }, skipRefreshConfig),

  /** 获取滑块拼图，返回背景图、拼图块及原始坐标尺寸。 */
  getSlideCaptcha: () =>
    ucenterRequest.post<UcenterResponse<SlideCaptchaData>>(
      '/api/captcha/slide',
      {},
      skipRefreshConfig,
    ),

  /** 校验滑块坐标并发送短信验证码。 */
  sendSmsCaptcha: (payload: SendSmsCaptchaPayload) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>(
      '/api/auth/send_sms_captcha',
      payload,
      skipRefreshConfig,
    ),

  /** 校验滑块坐标并发送邮箱验证码，具体用途通过 code_type 区分。 */
  sendEmailCode: (payload: SendEmailCaptchaPayload) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>('/api/auth/send_email', payload),

  updateUserInfo: (payload: UpdateUserInfoPayload) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>('/api/user/info/update', payload),

  bindEmail: (email: string, code: string) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>('/api/user/email/bind', {email, code}),

  updateEmail: (email: string, code: string) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>('/api/user/email/update', {email, code}),

  bindPhone: (phone: string, code: string) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>('/api/user/phone/bind', {
      phone,
      country_code: '86',
      code,
    }),

  updatePhone: (phone: string, code: string) =>
    ucenterRequest.post<UcenterResponse<{message: string}>>('/api/user/phone/update', {
      phone,
      country_code: '86',
      code,
    }),

  /** 客户端接口 2.18：获取 PostObject 表单上传参数。 */
  getAvatarPostObject: (contentType: string) =>
    ucenterRequest.post<UcenterResponse<AvatarPostObjectData>>('/api/user/avatar/post_object', {
      content_type: contentType,
    }),

  saveAvatar: (ossPath: string) =>
    ucenterRequest.post<UcenterResponse<AvatarSaveData>>('/api/user/avatar/save', {oss_path: ossPath}),

  /** 按 PostObject 表单方式上传；OSS 是第三方域名，不能携带账号中心 Authorization。 */
  uploadAvatarToOss: (data: AvatarPostObjectData, file: File) => {
    const form = new FormData();
    Object.entries(data.form_data).forEach(([key, value]) => form.append(key, value));
    form.append('file', file);
    return axios.post(data.upload_url, form, {timeout: 30_000});
  },

  logout: () => ucenterRequest.post<UcenterResponse<{message?: string}>>(
    '/api/auth/logout',
    {},
    logoutConfig,
  ),
};

/**
 * 浏览器统一账号会话。
 * access token 只保存在当前页面内存中，refresh token 由账号中心写入 HttpOnly Cookie。
 */

import {STORAGE_KEYS} from '@site/src/constants';

type RefreshHandler = () => Promise<string>;

export const ACCOUNT_REACTIVATION_REQUIRED_CODE = 10011;
export const AUTH_ACCOUNT_TERMINATED_EVENT = 'auth:account-terminated';

export interface AuthAccountTerminatedEventDetail {
  /** 去除首尾空格后的后端原始提示；空字符串表示无需展示。 */
  message: string;
  /** 清理失效账号后生成的新会话代次。 */
  generation: number;
}

/** 账号档案已失效，调用方不得将其当作 token 过期进行续期。 */
export class AccountSessionTerminatedError extends Error {
  readonly code = ACCOUNT_REACTIVATION_REQUIRED_CODE;
  readonly msg: string;
  readonly rawMessage: string;

  constructor(message: unknown) {
    const trimmedMessage = typeof message === 'string' ? message.trim() : '';
    super(trimmedMessage);
    this.name = 'AccountSessionTerminatedError';
    this.msg = trimmedMessage;
    this.rawMessage = trimmedMessage;
  }
}

let accessToken: string | null = null;
let accessTokenRevision = 0;
let authSessionGeneration = 0;
let refreshHandler: RefreshHandler | null = null;
let refreshPromise: Promise<string> | null = null;
let isRefreshBlockedByTermination = false;
let hasDispatchedAccountTermination = false;

/** 刷新期间登录态已被登出或新登录替换，旧刷新结果必须作废。 */
export class StaleAuthSessionError extends Error {
  constructor() {
    super('登录状态已发生变化，已忽略过期的刷新结果');
    this.name = 'StaleAuthSessionError';
  }
}

/** 读取当前页内存中的 access token。 */
export function getAccessToken(): string | null {
  return accessToken;
}

/** 登录或刷新成功后覆盖内存 token。 */
export function setAccessToken(token: string | null): void {
  accessToken = token || null;
  accessTokenRevision += 1;
}

/** 请求发出时记录会话代次，避免旧账号的迟到响应清除刚登录的新账号。 */
export function getAuthSessionGeneration(): number {
  return authSessionGeneration;
}

/**
 * 显式登录成功后开始一个新会话。
 * 此时只允许新会话继续请求，不提前解除持久化的静默恢复禁令；完整资料流程成功后再确认登录。
 */
export function startAuthSession(token: string): number {
  authSessionGeneration += 1;
  isRefreshBlockedByTermination = false;
  // 新显式会话允许再次发出一次终止事件，但持久恢复禁令仍需等完整登录成功后解除。
  hasDispatchedAccountTermination = false;
  setAccessToken(token);
  return authSessionGeneration;
}

/** 清除内存会话并推进代次，使所有旧请求和在途刷新结果失效。 */
export function clearAuthSession(): number {
  authSessionGeneration += 1;
  setAccessToken(null);
  return authSessionGeneration;
}

function writeRestoreBlocked(blocked: boolean): void {
  if (typeof window === 'undefined') return;
  try {
    if (blocked) localStorage.setItem(STORAGE_KEYS.AUTH_RESTORE_BLOCKED, '1');
    else localStorage.removeItem(STORAGE_KEYS.AUTH_RESTORE_BLOCKED);
  } catch {
    // 存储不可用时仍依赖当前页面内存状态阻断刷新。
  }
}

function writeTerminationMessage(message: string): void {
  if (typeof window === 'undefined') return;
  try {
    if (message) sessionStorage.setItem(STORAGE_KEYS.ACCOUNT_TERMINATION_MESSAGE, message);
    else sessionStorage.removeItem(STORAGE_KEYS.ACCOUNT_TERMINATION_MESSAGE);
  } catch {
    // sessionStorage 不可用时事件 detail 仍可把提示交给当前页面。
  }
}

/** 页面启动时据此跳过 refresh cookie 静默恢复，避免失效账号反复进入登录循环。 */
export function isAuthRestoreBlocked(): boolean {
  if (typeof window === 'undefined') return false;
  try {
    return isRefreshBlockedByTermination
      || localStorage.getItem(STORAGE_KEYS.AUTH_RESTORE_BLOCKED) === '1';
  } catch {
    return isRefreshBlockedByTermination;
  }
}

/** 登录页读取一次账号终止提示；空白文案不会产生提示。 */
export function consumeAccountTerminationMessage(): string {
  if (typeof window === 'undefined') return '';
  try {
    const message = sessionStorage.getItem(STORAGE_KEYS.ACCOUNT_TERMINATION_MESSAGE)?.trim() ?? '';
    sessionStorage.removeItem(STORAGE_KEYS.ACCOUNT_TERMINATION_MESSAGE);
    return message;
  } catch {
    return '';
  }
}

/**
 * 业务码 10011 的唯一会话终止入口。
 * 返回 false 表示响应属于旧会话，调用方只能丢弃该响应，不能影响当前账号。
 */
export function invalidateAccountSession(
  message: unknown,
  requestGeneration: number = authSessionGeneration,
): boolean {
  if (requestGeneration !== authSessionGeneration) return false;

  const trimmedMessage = typeof message === 'string' ? message.trim() : '';
  isRefreshBlockedByTermination = true;
  const generation = clearAuthSession();
  writeRestoreBlocked(true);
  writeTerminationMessage(trimmedMessage);

  if (!hasDispatchedAccountTermination && typeof window !== 'undefined') {
    hasDispatchedAccountTermination = true;
    window.dispatchEvent(new CustomEvent<AuthAccountTerminatedEventDetail>(
      AUTH_ACCOUNT_TERMINATED_EVENT,
      {detail: {message: trimmedMessage, generation}},
    ));
  }
  return true;
}

/** 显式登录和首次资料加载完整成功后，才允许后续页面启动静默恢复。 */
export function completeExplicitLogin(): void {
  isRefreshBlockedByTermination = false;
  hasDispatchedAccountTermination = false;
  writeRestoreBlocked(false);
  writeTerminationMessage('');
}

/** 注册真正执行 refresh_token 请求的方法，避免请求实例之间循环依赖。 */
export function registerRefreshHandler(handler: RefreshHandler): void {
  refreshHandler = handler;
}

/** 多个接口同时返回 401 时复用同一个刷新 Promise，防止 refresh token 被并发轮换。 */
export async function refreshAccessTokenOnce(): Promise<string> {
  if (isRefreshBlockedByTermination) throw new AccountSessionTerminatedError('');
  if (!refreshHandler) throw new Error('账号刷新能力尚未初始化');
  if (!refreshPromise) {
    const revisionBeforeRefresh = accessTokenRevision;
    refreshPromise = refreshHandler()
      .then(token => {
        if (accessTokenRevision !== revisionBeforeRefresh) {
          throw new StaleAuthSessionError();
        }
        setAccessToken(token);
        return token;
      })
      .catch(error => {
        if (accessTokenRevision !== revisionBeforeRefresh) {
          throw error instanceof StaleAuthSessionError ? error : new StaleAuthSessionError();
        }
        setAccessToken(null);
        throw error;
      })
      .finally(() => {
        refreshPromise = null;
      });
  }
  return refreshPromise;
}

/** 账号终止流程在调用 logout 前等待旧 refresh 收尾，防止 Cookie 轮换与退出请求竞态。 */
export async function waitForAuthRefreshSettlement(): Promise<void> {
  const pendingRefresh = refreshPromise;
  if (!pendingRefresh) return;
  try {
    await pendingRefresh;
  } catch {
    // 终止流程只关心刷新已经结束，刷新本身的错误由原调用方处理。
  }
}

/** 刷新失败时通知 AuthContext 清理页面登录态。 */
export function expireAuthSession(): void {
  clearAuthSession();
  if (typeof window !== 'undefined') window.dispatchEvent(new Event('auth:expired'));
}

"""Central configuration entry for HTTP and invocation limits."""

import math
import os
from dataclasses import dataclass
from pathlib import Path

from dotenv import dotenv_values


@dataclass(frozen=True)
class Settings:
    """Explicit resource budgets, not a promise of measured production capacity."""

    env_file: Path | None = None
    log_level: str = "INFO"
    max_active_calls: int = 8
    max_queued_calls: int = 24
    queue_timeout_seconds: float = 4.0
    request_timeout_seconds: float = 30.0
    record_timeout_seconds: float = 1.0
    max_response_bytes: int = 2_000_000
    max_request_bytes: int = 64_000
    allowed_hosts: tuple[str, ...] = (
        "localhost",
        "localhost:*",
        "127.0.0.1",
        "127.0.0.1:*",
        "[::1]",
        "[::1]:*",
    )
    allowed_origins: tuple[str, ...] = ("http://localhost:*", "http://127.0.0.1:*")

    def __post_init__(self) -> None:
        """Reject nonpositive, nonfinite, and inconsistent resource budgets."""
        for name in (
            "max_active_calls",
            "max_queued_calls",
            "max_response_bytes",
            "max_request_bytes",
        ):
            value = getattr(self, name)
            if type(value) is not int or value <= 0:
                raise ValueError(f"{name} must be a positive integer")
        for name in (
            "queue_timeout_seconds",
            "request_timeout_seconds",
            "record_timeout_seconds",
        ):
            value = getattr(self, name)
            if not math.isfinite(value) or value <= 0:
                raise ValueError(f"{name} must be finite and positive")
        if self.queue_timeout_seconds > self.request_timeout_seconds:
            raise ValueError("queue_timeout_seconds exceeds request_timeout_seconds")
        if self.max_response_bytes < 1024:
            raise ValueError("max_response_bytes must leave room for an error response")
        if self.log_level not in {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}:
            raise ValueError("log_level must be a standard uppercase logging level")
        if not self.allowed_hosts:
            raise ValueError("allowed_hosts cannot be empty")


def load_settings(env_file: Path | None = None) -> Settings:
    """Read only an explicitly supplied dotenv file, then apply environment overrides."""
    values = dotenv_values(env_file, interpolate=False) if env_file else {}
    values.update(os.environ)
    defaults = Settings()
    names = (
        "log_level",
        "max_active_calls",
        "max_queued_calls",
        "queue_timeout_seconds",
        "request_timeout_seconds",
        "record_timeout_seconds",
        "max_response_bytes",
        "max_request_bytes",
    )
    overrides: dict[str, object] = {}
    for name in names:
        key = f"MCP_{name.upper()}"
        if key in values:
            try:
                overrides[name] = type(getattr(defaults, name))(values[key])
            except (TypeError, ValueError) as error:
                raise ValueError(f"Invalid configuration field: {key}") from error
    for name in ("allowed_hosts", "allowed_origins"):
        key = f"MCP_{name.upper()}"
        if key in values:
            overrides[name] = tuple(
                part.strip() for part in (values[key] or "").split(",") if part.strip()
            )
    return Settings(env_file=env_file, **overrides)

