"""Public KITT names with legacy dispatch aliases."""

import re


def public_name(name: str) -> str:
    """Return the stable public tool identifier."""
    return name if name.startswith("KITT.") else "KITT." + name


def legacy_name(name: str) -> str:
    """Normalize only the public prefix; unknown names remain invalid."""
    return name.removeprefix("KITT.")


def public_text(text: str) -> str:
    """Qualify tool references without changing already qualified names."""
    return re.sub(
        r"(?<![A-Za-z0-9_.])(browse_catalog|hybrid_search|get_section)(?![A-Za-z0-9_.])",
        lambda match: public_name(match.group()),
        text,
    )

