"""Central configuration entry: platform target, budgets, and granted scopes."""

from __future__ import annotations

import math
import os
from dataclasses import dataclass
from pathlib import Path

from dotenv import dotenv_values

from ..catalog import Effect

_DEFAULT_SCOPES = (Effect.READ.scope, Effect.WRITE.scope)


@dataclass(frozen=True)
class Settings:
    """Explicit budgets and the perception platform target.

    ``enabled_scopes`` is the demo stand-in for OAuth scopes: a task runs only
    when its effect's scope is granted here. Deployment/execute is off by
    default so a demo cannot drive a robot without an explicit opt-in.
    """

    base_url: str = "http://192.168.25.14:8000"
    request_timeout_seconds: float = 30.0
    max_response_bytes: int = 2_000_000
    max_active_calls: int = 16
    max_queued_calls: int = 32
    queue_timeout_seconds: float = 4.0
    enabled_scopes: tuple[str, ...] = _DEFAULT_SCOPES
    log_level: str = "INFO"
    allowed_hosts: tuple[str, ...] = (
        "localhost",
        "localhost:*",
        "127.0.0.1",
        "127.0.0.1:*",
        "[::1]",
        "[::1]:*",
    )
    allowed_origins: tuple[str, ...] = ("http://localhost:*", "http://127.0.0.1:*")

    def __post_init__(self) -> None:
        if not self.base_url.startswith(("http://", "https://")):
            raise ValueError("base_url must be an http(s) URL")
        for name in (
            "request_timeout_seconds",
            "queue_timeout_seconds",
        ):
            value = getattr(self, name)
            if not math.isfinite(value) or value <= 0:
                raise ValueError(f"{name} must be finite and positive")
        for name in ("max_response_bytes", "max_active_calls", "max_queued_calls"):
            value = getattr(self, name)
            if type(value) is not int or value <= 0:
                raise ValueError(f"{name} must be a positive integer")
        if self.queue_timeout_seconds > self.request_timeout_seconds:
            raise ValueError("queue_timeout_seconds exceeds request_timeout_seconds")
        known = {e.scope for e in Effect}
        unknown = set(self.enabled_scopes) - known
        if unknown:
            raise ValueError(f"unknown scopes: {sorted(unknown)}")
        if self.log_level not in {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}:
            raise ValueError("log_level must be a standard uppercase logging level")

    def scope_enabled(self, effect: Effect) -> bool:
        return effect.scope in self.enabled_scopes


def _split(value: str) -> tuple[str, ...]:
    return tuple(part.strip() for part in value.split(",") if part.strip())


def load_settings(env_file: Path | None = None) -> Settings:
    """Read an optional dotenv file, then apply PERCEPTION_/MCP_ env overrides."""
    values = dotenv_values(env_file, interpolate=False) if env_file else {}
    values.update(os.environ)
    defaults = Settings()
    overrides: dict[str, object] = {}

    mapping = {
        "PERCEPTION_BASE_URL": ("base_url", str),
        "PERCEPTION_REQUEST_TIMEOUT_SECONDS": ("request_timeout_seconds", float),
        "PERCEPTION_MAX_RESPONSE_BYTES": ("max_response_bytes", int),
        "MCP_MAX_ACTIVE_CALLS": ("max_active_calls", int),
        "MCP_MAX_QUEUED_CALLS": ("max_queued_calls", int),
        "MCP_QUEUE_TIMEOUT_SECONDS": ("queue_timeout_seconds", float),
        "MCP_LOG_LEVEL": ("log_level", str),
    }
    for key, (field, caster) in mapping.items():
        if key in values and values[key] is not None:
            try:
                overrides[field] = caster(values[key])
            except (TypeError, ValueError) as error:
                raise ValueError(f"Invalid configuration field: {key}") from error

    if "PERCEPTION_SCOPES" in values and values["PERCEPTION_SCOPES"] is not None:
        overrides["enabled_scopes"] = _split(values["PERCEPTION_SCOPES"])
    for key, field in (
        ("MCP_ALLOWED_HOSTS", "allowed_hosts"),
        ("MCP_ALLOWED_ORIGINS", "allowed_origins"),
    ):
        if key in values and values[key] is not None:
            overrides[field] = _split(values[key])

    return Settings(**overrides)  # type: ignore[arg-type]

"""HTTP adapter to the perception platform REST API.

Translates a curated catalog Task plus validated arguments into one request.
Only path/query/body parameters declared by the task are used; the path
template is filled from declared path params, never from free-form input.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any
from urllib.parse import quote

import httpx

from ..catalog import Task


class PerceptionClientError(RuntimeError):
    """Raised when the platform call cannot be completed or decoded."""


@dataclass(frozen=True)
class PlatformResponse:
    status_code: int
    ok: bool
    data: Any

    @property
    def encoded_bytes(self) -> int:
        return len(json.dumps(self.data, ensure_ascii=False).encode("utf-8"))


def _build_request(task: Task, arguments: dict[str, Any]) -> tuple[str, dict[str, Any], Any]:
    path_params: dict[str, Any] = {}
    query_params: dict[str, Any] = {}
    body_params: dict[str, Any] = {}
    for param in task.params:
        if param.name not in arguments:
            continue
        value = arguments[param.name]
        if param.location == "path":
            path_params[param.name] = value
        elif param.location == "query":
            query_params[param.name] = value
        elif param.location == "body":
            body_params[param.name] = value

    try:
        path = task.path.format(**{k: quote(str(v), safe="") for k, v in path_params.items()})
    except KeyError as error:
        raise PerceptionClientError(f"missing path parameter {error}") from error

    body: Any = None
    if body_params:
        # A single 'payload' object is sent as the request body directly;
        # otherwise the declared body params form the object.
        if set(body_params) == {"payload"} and isinstance(body_params["payload"], dict):
            body = body_params["payload"]
        else:
            body = {k: v for k, v in body_params.items() if k != "payload"}
            extra = body_params.get("payload")
            if isinstance(extra, dict):
                body.update(extra)
    return path, query_params, body


class PerceptionClient:
    """Owns one httpx.AsyncClient for the service lifetime."""

    def __init__(self, base_url: str, timeout_seconds: float) -> None:
        self._base_url = base_url.rstrip("/")
        self._client = httpx.AsyncClient(
            base_url=self._base_url,
            timeout=httpx.Timeout(timeout_seconds),
            headers={"Accept": "application/json"},
        )

    async def aclose(self) -> None:
        await self._client.aclose()

    async def call(self, task: Task, arguments: dict[str, Any]) -> PlatformResponse:
        path, query, body = _build_request(task, arguments)
        try:
            response = await self._client.request(
                task.method, path, params=query or None, json=body
            )
        except httpx.HTTPError as error:
            raise PerceptionClientError(f"platform request failed: {error.__class__.__name__}") from error

        data = _decode(response)
        return PlatformResponse(status_code=response.status_code, ok=response.is_success, data=data)


def _decode(response: httpx.Response) -> Any:
    if not response.content:
        return None
    try:
        return response.json()
    except ValueError:
        text = response.text
        return {"raw_text": text[:4000]}

