"""Business logic for the three progressive-disclosure meta tools.

The catalog is a whitelist: agents discover groups, then tasks, then run one
declared task. ``run_task`` validates arguments against the task's own schema,
enforces the effect's scope, and only then calls the platform. There is no
free-form path or method -- this is a curated dispatcher, not a generic proxy.
"""

from __future__ import annotations

from typing import Any

from ..catalog import CATALOG, Task, find_group, find_task
from ..client.perception import PerceptionClient, PerceptionClientError
from ..config.settings import Settings

_TYPE_CHECKS: dict[str, tuple[type, ...]] = {
    "string": (str,),
    "integer": (int,),
    "number": (int, float),
    "boolean": (bool,),
    "object": (dict,),
    "array": (list,),
}


class DispatchError(Exception):
    """A user-facing failure with a stable code."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def list_groups() -> dict[str, Any]:
    """Level 1 disclosure: the capability map, no per-task schemas."""
    return {
        "groups": [
            {
                "group_id": group.group_id,
                "title": group.title,
                "description": group.description,
                "task_count": len(group.tasks),
                "effects": group.effects(),
            }
            for group in CATALOG
        ]
    }


def list_tasks(group_id: str) -> dict[str, Any]:
    """Level 2 disclosure: tasks and input schemas for one group."""
    group = find_group(group_id)
    if group is None:
        raise DispatchError(
            "UNKNOWN_GROUP",
            f"未知组 '{group_id}'；先调用 KITT.perception_groups 查看可用组。",
        )
    return {
        "group_id": group.group_id,
        "title": group.title,
        "tasks": [
            {
                "task_id": task.task_id,
                "title": task.title,
                "description": task.description,
                "effect": task.effect.value,
                "required_scope": task.effect.scope,
                "input_schema": task.input_schema(),
            }
            for task in group.tasks
        ],
    }


def _validate_arguments(task: Task, arguments: dict[str, Any]) -> dict[str, Any]:
    declared = {p.name: p for p in task.params}
    unknown = set(arguments) - set(declared)
    if unknown:
        raise DispatchError(
            "INVALID_ARGUMENT", f"任务 '{task.task_id}' 不接受参数: {sorted(unknown)}"
        )
    for name, param in declared.items():
        if param.required and name not in arguments:
            raise DispatchError("INVALID_ARGUMENT", f"缺少必填参数 '{name}'")
        if name in arguments:
            expected = _TYPE_CHECKS.get(param.type, (object,))
            value = arguments[name]
            # bool is a subclass of int; keep them distinct for integer/number.
            if param.type in ("integer", "number") and isinstance(value, bool):
                raise DispatchError("INVALID_ARGUMENT", f"参数 '{name}' 应为数字")
            if not isinstance(value, expected):
                raise DispatchError(
                    "INVALID_ARGUMENT",
                    f"参数 '{name}' 应为 {param.type}，实际为 {type(value).__name__}",
                )
    return {k: v for k, v in arguments.items()}


async def run_task(
    task_id: str,
    arguments: dict[str, Any],
    *,
    client: PerceptionClient,
    settings: Settings,
) -> dict[str, Any]:
    """Level 3: validate, authorize, call the platform, return a bounded result."""
    task = find_task(task_id)
    if task is None:
        raise DispatchError(
            "UNKNOWN_TASK",
            f"未知任务 '{task_id}'；先调用 KITT.perception_tasks 查看组内任务。",
        )
    validated = _validate_arguments(task, arguments)
    if not settings.scope_enabled(task.effect):
        raise DispatchError(
            "SCOPE_NOT_GRANTED",
            f"任务 '{task_id}' 需要授权范围 {task.effect.scope}，当前未授予。",
        )
    try:
        response = await client.call(task, validated)
    except PerceptionClientError as error:
        raise DispatchError("PLATFORM_UNAVAILABLE", str(error)) from error

    data = response.data
    truncated = False
    if response.encoded_bytes > settings.max_response_bytes:
        data = {
            "truncated": True,
            "note": "响应超过大小上限，已截断；请缩小查询范围或使用更具体的任务。",
            "preview": str(data)[: settings.max_response_bytes // 2],
        }
        truncated = True

    group_id = task_id.split(".", 1)[0]
    return {
        "group_id": group_id,
        "task_id": task_id,
        "effect": task.effect.value,
        "ok": response.ok,
        "status_code": response.status_code,
        "truncated": truncated,
        "data": data,
    }

