def _text(payload: Any) -> TextContent:
    return TextContent(type="text", text=json.dumps(payload, ensure_ascii=False))


def _result(payload: Any, *, is_error: bool = False) -> CallToolResult:
    structured = payload if isinstance(payload, dict) else {"data": payload}
    return CallToolResult(
        content=[_text(structured)],
        structuredContent=structured,
        isError=is_error,
    )


def _require_resources(provider: ResourceProvider) -> ServiceResources:
    resources = provider.resources
    if resources is None or not resources.started:
        raise MCPError(ErrorData(code=-32603, message="Server lifecycle is not active"))
    return resources


async def _read_task_data(
    task_id: str, arguments: dict[str, Any], resources: ServiceResources
) -> Any:
    """Read-only resource fetch through the same validated dispatch path."""
    task = find_task(task_id)
    if task is None:  # pragma: no cover - catalog is static
        raise MCPError(ErrorData(code=-32603, message=f"catalog task missing: {task_id}"))
    response = await resources.client.call(task, arguments)
    return response.data


def _catalog_document() -> dict[str, Any]:
    from ..tools.dispatch import list_groups as _groups, list_tasks as _tasks

    groups = _groups()["groups"]
    detailed = [_tasks(g["group_id"]) for g in groups]
    return {"server": SERVER_NAME, "version": __version__, "groups": detailed}


def build_mcp_server(provider: ResourceProvider, settings: Settings) -> Server:
    tool_schemas = {name: model.model_json_schema() for name, _, model in _TOOLS}

    async def on_list_tools(
        ctx: ServerRequestContext, params: PaginatedRequestParams | None
    ) -> ListToolsResult:
        return ListToolsResult(
            tools=[
                Tool(
                    name=public_name(name),
                    title=public_name(name),
                    description=desc,
                    inputSchema=tool_schemas[name],
                    annotations=ToolAnnotations(
                        title=public_name(name),
                        readOnlyHint=name != "perception_run",
                        destructiveHint=False,
                    ),
                )
                for name, desc, _ in _TOOLS
            ]
        )

    async def on_call_tool(
        ctx: ServerRequestContext, params: CallToolRequestParams
    ) -> CallToolResult:
        name = internal_name(params.name)
        arguments = params.arguments or {}
        resources = _require_resources(provider)
        try:
            if name == "perception_groups":
                GroupsInput.model_validate(arguments)
                return _result(list_groups())
            if name == "perception_tasks":
                parsed = TasksInput.model_validate(arguments)
                return _result(list_tasks(parsed.group))
            if name == "perception_run":
                parsed = RunInput.model_validate(arguments)
                payload = await run_task(
                    parsed.task,
                    parsed.arguments,
                    client=resources.client,
                    settings=resources.settings,
                )
                return _result(payload, is_error=not payload.get("ok", False))
        except DispatchError as error:
            return _result({"error": error.code, "message": error.message}, is_error=True)
        except Exception as error:  # noqa: BLE001 - safe boundary fallback
            return _result(
                {"error": "INTERNAL_ERROR", "message": error.__class__.__name__},
                is_error=True,
            )
        raise MCPError(ErrorData(code=-32602, message="Unknown tool"))

    async def on_list_resources(
        ctx: ServerRequestContext, params: PaginatedRequestParams | None
    ) -> ListResourcesResult:
        return ListResourcesResult(resources=list(_STATIC_RESOURCES))

    async def on_list_resource_templates(
        ctx: ServerRequestContext, params: PaginatedRequestParams | None
    ) -> ListResourceTemplatesResult:
        return ListResourceTemplatesResult(resourceTemplates=list(_RESOURCE_TEMPLATES))

    async def on_read_resource(
        ctx: ServerRequestContext, params: ReadResourceRequestParams
    ) -> ReadResourceResult:
        resources = _require_resources(provider)
        uri = str(params.uri)
        parsed = urlsplit(uri)
        path = parsed.path  # e.g. "/catalog", "/modules", "/modules/x/status"

        async def contents(data: Any) -> ReadResourceResult:
            text = json.dumps(data, ensure_ascii=False)
            return ReadResourceResult(
                contents=[
                    TextResourceContents(uri=uri, mimeType="application/json", text=text)
                ]
            )

        if uri == "perception://catalog":
            return contents(_catalog_document())
        if uri == "perception://modules":
            return contents(await _read_task_data("catalog.list_modules", {}, resources))
        if uri == "perception://health":
            return contents(await _read_task_data("catalog.health", {}, resources))

        parts = [unquote(p) for p in path.split("/") if p]
        if len(parts) == 3 and parts[0] == "modules" and parts[2] == "status":
            return contents(
                await _read_task_data(
                    "catalog.module_status", {"module_id": parts[1]}, resources
                )
            )
        raise MCPError(ErrorData(code=-32002, message=f"Resource not found: {uri}"))

    async def on_list_prompts(
        ctx: ServerRequestContext, params: PaginatedRequestParams | None
    ) -> ListPromptsResult:
        return ListPromptsResult(prompts=list(_PROMPTS))

    async def on_get_prompt(
        ctx: ServerRequestContext, params: GetPromptRequestParams
    ) -> GetPromptResult:
        args = params.arguments or {}
        if params.name == "perception.pipeline":
            module_id = args.get("module_id", "<module_id>")
            project_id = args.get("project_id", "<project_id>")
            text = (
                f"目标：在感知平台把模块 {module_id}、项目 {project_id} 走完训练到部署。\n"
                "步骤（每步用 KITT.perception_run，任务名见 KITT.perception_tasks）：\n"
                f"1. 提交训练：training.create_run {{module_id={module_id}, project_id={project_id}}}\n"
                "2. 轮询进度：training.run_progress / training.run_status\n"
                "3. 训练成功后评测：evaluation.create，再 evaluation.result 看指标\n"
                "4. 构建 Engine：engine.builder_config 选目标，engine.build\n"
                "5. 部署（需 perception:execute）：deployment.deployable_builds 确认，deployment.deploy\n"
                "6. 跟踪部署：deployment.status\n"
                "注意：写操作需 perception:write，部署需 perception:execute；未授予时任务会被拒绝。"
            )
            return GetPromptResult(
                description="训练到部署流水线",
                messages=[PromptMessage(role="user", content=_text_string(text))],
            )
        if params.name == "perception.inspect_run":
            module_id = args.get("module_id", "<module_id>")
            run_id = args.get("run_id", "<run_id>")
            text = (
                f"排查训练 module_id={module_id}, run_id={run_id}：\n"
                "1. training.run_status 看整体状态\n"
                "2. training.run_progress 看进度指标\n"
                "3. training.run_logs 看日志定位报错\n"
                "4. training.run_artifacts 确认产物是否生成\n"
                "全部为只读任务，无需写授权。"
            )
            return GetPromptResult(
                description="训练排查",
                messages=[PromptMessage(role="user", content=_text_string(text))],
            )
        raise MCPError(ErrorData(code=-32602, message=f"Unknown prompt: {params.name}"))

    return Server(
        SERVER_NAME,
        version=__version__,
        title=SERVER_NAME,
        instructions=(
            "KITT.Perception 封装 Galbot 感知模型平台。渐进披露：先 KITT.perception_groups 看组，"
            "再 KITT.perception_tasks 看组内任务与入参，最后 KITT.perception_run 执行单个任务。"
            "只读任务随时可用；训练/评测/构建等写操作需 perception:write，机器人部署需 perception:execute，"
            "未授予会返回 SCOPE_NOT_GRANTED。资源 perception://catalog 提供完整目录。"
        ),
        on_list_tools=on_list_tools,
        on_call_tool=on_call_tool,
        on_list_resources=on_list_resources,
        on_list_resource_templates=on_list_resource_templates,
        on_read_resource=on_read_resource,
        on_list_prompts=on_list_prompts,
        on_get_prompt=on_get_prompt,
    )


def _text_string(text: str) -> TextContent:
    return TextContent(type="text", text=text)

